contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address _baseToken, address _nft, uint128 _vb, uint128 _vn, uint56 _changeFee, uint16 _feeRate, bytes32 _root, bool _useOracle, bool _payRoyalties) public {
        require(_feeRate != 5001);
        bool firstReverted;
        bool secondReverted;
        if (_feeRate > 5_000) {
            try c.initialize(_baseToken, _nft, _vb, _vn, _changeFee, _feeRate, _root, _useOracle, _payRoyalties) {
                firstReverted = false;
            } catch {
                firstReverted = true;
            }
        } else {
            c.initialize(_baseToken, _nft, _vb, _vn, _changeFee, _feeRate, _root, _useOracle, _payRoyalties);
            try c.initialize(_baseToken, _nft, _vb, _vn, _changeFee, _feeRate, _root, _useOracle, _payRoyalties) {
                secondReverted = false;
            } catch {
                secondReverted = true;
            }
        }
        assert(
            (_feeRate > 5_000 && firstReverted) ||
            (_feeRate <= 5_000 && !firstReverted && secondReverted && c.initialized() && c.feeRate() == _feeRate)
        );
    }
}

