contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        bool revertedFirst;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            revertedFirst = false;
        } catch {
            revertedFirst = true;
        }

        bool revertedSecond;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            revertedSecond = false;
        } catch {
            revertedSecond = true;
        }

        if (_feeRate > 5_000) {
            assert(revertedFirst);
        } else {
            assert(
                !revertedFirst &&
                c.feeRate() == _feeRate &&
                c.initialized() &&
                c.baseToken() == _baseToken &&
                c.nft() == _nft &&
                c.virtualBaseTokenReserves() == _virtualBaseTokenReserves &&
                c.virtualNftReserves() == _virtualNftReserves &&
                c.changeFee() == _changeFee &&
                c.merkleRoot() == _merkleRoot &&
                c.useStolenNftOracle() == _useStolenNftOracle &&
                c.payRoyalties() == _payRoyalties &&
                revertedSecond
            );
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint16 _feeRate,
        uint256 inputAmount
    ) public {
        require(_feeRate <= 5_000);
        require(_virtualNftReserves > 0);
        require(uint256(_virtualBaseTokenReserves) <= 1e18);
        require(inputAmount <= 1e18);

        c.initialize(
            address(0),
            address(0),
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            0,
            _feeRate,
            bytes32(0),
            false,
            false
        );

        (uint256 netOutputAmount, uint256 feeAmount, uint256 protocolFeeAmount) =
            c.sellQuote(inputAmount);

        uint256 grossOutput =
            (uint256(_virtualBaseTokenReserves) * inputAmount) /
            (uint256(_virtualNftReserves) + inputAmount);

        assert(
            feeAmount + protocolFeeAmount + netOutputAmount == grossOutput &&
            feeAmount == (grossOutput * uint256(_feeRate)) / 10_000 &&
            protocolFeeAmount == (grossOutput * uint256(c.factory().code.length == 0 ? 0 : Factory(c.factory()).protocolFeeRate())) / 10_000
        );
    }

    receive() external payable {}
}

