contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint128 base, uint128 nftRes, uint16 rate, uint32 outputAmount) public {
        require(rate <= 5000);
        require(nftRes > 1);
        require(uint256(outputAmount) < uint256(nftRes) - 1);
        require(uint256(base) <= 2**160);

        c.initialize(address(0), address(0), base, nftRes, 0, rate, bytes32(0), false, false);

        (uint256 netInput, uint256 fee, uint256 protocolFee) = c.buyQuote(uint256(outputAmount));

        uint256 input = netInput - fee - protocolFee;

        assert(fee == input * uint256(rate) / 10_000 && fee <= input / 2);
    }
}

contract InvMutTest {
