            address(0),
            address(0),
            0,
            reserves,
            0,
            rate,
            bytes32(0),
            false,
            false
        );

        bool reverted;
        uint256 netInput;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        try c.buyQuote(0) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netInput = n;
            feeAmount = f;
