contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint56 changeFee, uint256 nftCount) public {
        require(uint256(changeFee) <= 1000);
        require(nftCount > 0 && nftCount <= 10**12);

        c.initialize(
            address(0),
            address(0),
            1e18,
            1e18,
            changeFee,
            0,
            bytes32(0),
            false,
            false
        );

        uint256 inputAmount = nftCount * 1e18;

        bool reverted;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        try c.changeFeeQuote(inputAmount) returns (uint256 f, uint256 p) {
            reverted = false;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        assert(
            !reverted &&
            feeAmount == nftCount * uint256(changeFee) * 10**14 &&
            protocolFeeAmount <= feeAmount
        );
    }
}

